/// <summary>
/// PaffH 19.08.25
/// get formHandler of caller
/// </summary>
/// <param name = "_formRun">FormRun</param>
/// <returns>NDXBVEMailRequestControlCenterFormI</returns>
public static NDXBVEMailRequestControlCenterFormI formHandlerCaller(FormRun _formRun)
{

    NDXBVEMailRequestControlCenterFormI formHandlerCaller;
    Args args = _formRun.args();
    if (args && args.caller() is NDXFormHandlerIncludedI)
    {
        NDXFormHandlerIncludedI nDXFormHandlerIncludedCaller = args.caller() as NDXFormHandlerIncludedI;
        if (nDXFormHandlerIncludedCaller)
        {
            NDXBVEMailRequestControlCenterForm formHandler = nDXFormHandlerIncludedCaller.parmFormhandler();
            if (formHandler is NDXBVEMailRequestControlCenterFormI)
            {
                formHandlerCaller = formHandler as NDXBVEMailRequestControlCenterFormI;
            }
        }
    }
    return formHandlerCaller;
}

