/// <summary>
/// PaffH 20.08.25
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(AVAKBVBuildingProjectSearch, NDXValuesFromBVEmailRequest), FormControlEventType::Clicked),
    SuppressBPWarning('BPParameterNotUsed', '"e" is not used')]
public static void NDXValuesFromBVEmailRequest_OnClicked(FormControl sender, FormControlEventArgs e)
{
    FormRun formRunLocal = sender.formRun();
    NDXBVEMailRequestControlCenterFormI formHandlerCaller = NDXAVAKBVBuildingProjectSearch_frm_EventHandler::formHandlerCaller(formRunLocal);
    NDXKBVBuildingProjectSearchFormI formHandlerFormRun = NDXAVAKBVBuildingProjectSearch_frm_EventHandler::formHandlerFormRun(formRunLocal);
    NDXBVSearchContract bvSearchContract;

    if (formHandlerCaller)
    {
        bvSearchContract = formHandlerCaller.fillContract();
        formHandlerCaller.parmBVSearchContract(bvSearchContract);
        if (bvSearchContract && formHandlerFormRun)
        {
            formHandlerFormRun.fillFormValuesFromContract(bvSearchContract);
        }
    }
}

