/// <summary>
/// PaffH 20.08.25
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(AVAKBVBuildingProjectSearch, NDXAssignBVToEmailRequest), FormControlEventType::Clicked),
    SuppressBPWarning('BPParameterNotUsed', '"e" is not used')]
public static void NDXAssignBVToEmailRequest_OnClicked(FormControl sender, FormControlEventArgs e)
{
    FormRun formrun = sender.formRun();
    FormDataSource fds = formrun.dataHelper().FindDataSource(formDataSourceStr(AVAKBVBuildingProjectSearch, KCS_KBVBuildingProjectTable));
    KCS_KBVBuildingProjectTable kCS_KBVBuildingProjectTable = fds.cursor();
    NDXBVEMailRequestControlCenterFormI formHandlerCaller = NDXAVAKBVBuildingProjectSearch_frm_EventHandler::formHandlerCaller(formRun);
    formHandlerCaller.setBuildingProject(kCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID);
    formrun.close();
}
